/**
 * Add a listener for a given event.
 *
 * @param {string} eventName - Event identifier.
 * @param {Function} handler - Callback for event payload.
 * @param {Object} [options]
 * @param {boolean} [options.once=false] - Register a one-time listener.
 * @returns {void}
 */
export function onEvent(eventName: string, handler: Function, options?: {
    once?: boolean;
}): void;
/**
 * Remove a listener for a given event.
 *
 * @param {string} eventName - Event identifier.
 * @param {Function} handler - Callback to remove.
 * @param {Object} [options]
 * @param {Object} [options.context=null] - Optional listener context.
 * @param {boolean} [options.once=false] - Match a once listener.
 * @returns {void}
 */
export function offEvent(eventName: string, handler: Function, options?: {
    context?: any;
    once?: boolean;
}): void;
/**
 * Dispatch a payload to listeners for a given event.
 *
 * @param {string} eventName - Event identifier.
 * @param {*} [payload] - Optional payload.
 * @returns {void}
 */
export function emitEvent(eventName: string, payload?: any): void;
/**
 * Remove all event listeners.
 * Call this on Physics.dispose() to prevent memory leaks across HMR reloads.
 *
 * @returns {void}
 */
export function resetEventEmitter(): void;
